// Every non-final species and all four drop qualities have a purpose in growth.
const TIER_FORGE_EXCLUDED=new Set(['ex100','ex100skill']);
const TIER_FORGE_STAGES=[];
for(const region of REGIONS)for(let quality=0;quality<4;quality++)for(const boss of [false,true]){
 const ids=Object.values(SPECIES).filter(s=>s.region===region.id&&!!s.boss===boss&&!TIER_FORGE_EXCLUDED.has(s.id)).map(s=>s.id+':'+quality).sort();
 if(ids.length)TIER_FORGE_STAGES.push({region:region.id,quality,boss,order:region.id+quality*3+(boss?2:0),cost:Object.fromEntries(ids.map(id=>[id,(boss?[5,3,2,1]:[8,5,3,1])[quality]]))});
}
TIER_FORGE_STAGES.sort((a,b)=>a.order-b.order||a.region-b.region||a.quality-b.quality||Number(a.boss)-Number(b.boss));
const TIER_FORGE_MATERIALS=TIER_FORGE_STAGES.flatMap(s=>Object.entries(s.cost));
const TIER_ABILITY_CAP=20;
for(const recipe of FORGE_RECIPES){const r=recipe.rank-1,role=recipe.role;recipe.cost={['r'+r+'e'+role+':0']:5,['r'+r+'e'+((role+2)%8)+':0']:3,['r'+r+'e'+((role+5)%8)+':'+(recipe.rank>=5?1:0)]:2};recipe.goldCost=20+recipe.rank*15;}
const multiRecipeStatus=forgeRecipeStatus;forgeRecipeStatus=recipe=>{const s=multiRecipeStatus(recipe);return s==='製作できます'&&p.gold<recipe.goldCost?'ゴールドが不足しています':s;};
// Keep the original transaction and its full save-failure rollback for materials,
// inventory and currency together. Never charge for a rejected recipe.
const multiCraftRecipe=craftForgeRecipe;craftForgeRecipe=id=>{const recipe=FORGE_RECIPES.find(r=>r.id===id);if(forgeRecipeStatus(recipe)!=='製作できます')return multiCraftRecipe(id);const original=worldTransaction;worldTransaction=change=>original(()=>{p.gold-=recipe.goldCost;change();});try{return multiCraftRecipe(id);}finally{worldTransaction=original;}};
const multiRecipeDetail=forgeRecipeDetail;forgeRecipeDetail=recipe=>multiRecipeDetail(recipe).replace('<h4>必要素材</h4>','<h4>必要素材</h4><p class="forge-gold">◈ 所持 '+p.gold.toLocaleString()+' G ／ 使用 '+recipe.goldCost+' G</p>');
function tierForgeAbilities(item){return item.mods?.length?item.mods:[{key:'base',value:item.value}];}
function tierForgeCounts(item){return item.tierRolls||tierForgeAbilities(item).map(()=>0);}
function tierForgeLevel(item){return item?tierForgeCounts(item).reduce((a,n)=>a+n,0):0;}
function tierForgeMax(item){return tierForgeAbilities(item).length*TIER_ABILITY_CAP;}
function tierForgeQuote(item){const level=tierForgeLevel(item),max=tierForgeMax(item);if(level>=max)return null;const first=Object.keys(TIER_FORGE_STAGES[0].cost).length,remaining=TIER_FORGE_MATERIALS.length-first;const from=level===0?0:first+Math.floor((level-1)*remaining/(max-1)),to=level===0?first:first+Math.floor(level*remaining/(max-1));return{level,next:level+1,max,cost:Object.fromEntries(TIER_FORGE_MATERIALS.slice(from,to)),gold:40+Math.floor(level/(max-1)*960)};}
function tierForgeResolve(key){if(typeof key!=='string')return null;const [area,id]=key.split(':');if(area==='slot'&&GEAR_SLOTS.includes(id))return p[id];if((area==='bag'||area==='stash')&&/^(0|[1-9]\d*)$/.test(id))return p[area]?.[+id];return null;}
function tierForgeStatus(key){const item=tierForgeResolve(key),q=item&&tierForgeQuote(item);if(!item||!GEAR_SLOTS.includes(item.slot))return '装備を選択';if(!villageOpen)return '村の鍛冶屋で強化できます';if(!q)return '最大ティア';if(p.gold<q.gold)return 'ゴールド不足';if(Object.entries(q.cost).some(([id,n])=>(campaign().materials[id]||0)<n))return '素材不足';return '強化できます';}
function tierForgeValue(value,level){return Math.round(value*(1+(level+1)*.05)/(1+level*.05)*10000)/10000;}
function upgradeEquipmentTier(key){if(tierForgeStatus(key)!=='強化できます'){say(tierForgeStatus(key));return false;}const item=tierForgeResolve(key),q=tierForgeQuote(item),counts=tierForgeCounts(item),eligible=counts.map((n,i)=>n<TIER_ABILITY_CAP?i:-1).filter(i=>i>=0),chosen=eligible[Math.floor(Math.random()*eligible.length)],ability=tierForgeAbilities(item)[chosen];if(!worldTransaction(()=>{p.gold-=q.gold;for(const [id,n]of Object.entries(q.cost))campaign().materials[id]-=n;if(item.mods?.length)item.mods[chosen].value=tierForgeValue(ability.value,counts[chosen]);else item.value=tierForgeValue(item.value,counts[chosen]);item.tierRolls=[...counts];item.tierRolls[chosen]++;}))return false;showTierForge(key);say((ability.key==='base'?gearBaseLabel(item):MODS[ability.key][0])+'を強化 '+item.tierRolls[chosen]+' / '+TIER_ABILITY_CAP);return true;}
const tierSaveItem=saveItem;saveItem=(item,slot)=>{const out=tierSaveItem(item,slot);if(out&&item.tierRolls!==undefined){if(!Array.isArray(item.tierRolls)||item.tierRolls.length!==tierForgeAbilities(item).length||item.tierRolls.some(n=>!Number.isInteger(n)||n<0||n>TIER_ABILITY_CAP))throw Error('能力ティアが不正です');out.tierRolls=[...item.tierRolls];}return out;};
const tierRerollBase=reroll;reroll=(slot,kind)=>{if(kind==='mods'&&p[slot]&&tierForgeLevel(p[slot])>0){say('ティア強化済みの装備は付与能力を再抽選できません');return false;}return tierRerollBase(slot,kind);};
const tierItemDetails=itemDetails;itemDetails=item=>tierItemDetails(item)+(item?'<small>ティア強化 '+tierForgeLevel(item)+' / '+tierForgeMax(item)+'回</small>':'');
let tierForgeSelected=null,tierForgeArea='slot';
function tierForgeItems(){return tierForgeArea==='slot'?GEAR_SLOTS.filter(s=>p[s]).map(s=>({key:'slot:'+s,item:p[s]})):(p[tierForgeArea]||[]).map((item,i)=>({key:tierForgeArea+':'+i,item}));}
function tierForgeDetail(key){const item=tierForgeResolve(key),box=$('tierForgeDetail');if(!item||!box)return;tierForgeSelected=key;const q=tierForgeQuote(item),stat=n=>Number(n.toFixed(4)).toLocaleString();
 const counts=tierForgeCounts(item),remaining=counts.filter(n=>n<TIER_ABILITY_CAP).length;
 box.innerHTML='<h3>'+gearEscape(item.name)+'</h3><p>強化 '+tierForgeLevel(item)+' / '+tierForgeMax(item)+'回 · 各能力 '+TIER_ABILITY_CAP+'回まで</p><div class="tier-stat-preview">'+tierForgeAbilities(item).map((m,i)=>'<p><strong>'+(m.key==='base'?gearBaseLabel(item):MODS[m.key][0])+'</strong> '+stat(m.value)+' <small> · '+counts[i]+' / '+TIER_ABILITY_CAP+'</small>'+(counts[i]<TIER_ABILITY_CAP?'<br><small>抽選時 → '+stat(tierForgeValue(m.value,counts[i]))+' · 確率 '+(100/remaining).toFixed(1)+'%</small>':' · MAX')+'</p>').join('')+'</div>'+(q?'<p>◈ 所持 '+p.gold.toLocaleString()+' G ／ 使用 '+q.gold+' G</p><h4>必要素材</h4><div class="material-grid">'+Object.entries(q.cost).map(([id,n])=>materialTile(id,n)).join('')+'</div><p role="status">'+tierForgeStatus(key)+'</p><button onclick="upgradeEquipmentTier(\''+key+'\')" '+(tierForgeStatus(key)!=='強化できます'?'disabled':'')+'>ランダムな能力を1段階強化</button>':'<p>すべての能力が最大ティアです</p>')+'<details><summary>ティア強化について</summary><p>上限未満の能力から1つを等確率で選びます。各能力20回で上限になり、以後は抽選から外れます。最終的には全能力が上限になります。付与能力がない装備は基礎値を強化します。</p><p>強化済みの装備は付与能力の再抽選ができません。ソケット・ジェム・タグは保持されます。最大強化までに通常の敵・ボスの全品質素材を使用します。最終装備とランダムスキル生成専用の素材は不要です。</p></details>';
 for(const b of $('card').querySelectorAll('[data-tier-item]'))b.setAttribute('aria-pressed',String(b.dataset.tierItem===key));
}
function showTierForge(selected=tierForgeSelected){if(!villageOpen){say('村の鍛冶屋で利用できます');return false;}const items=tierForgeItems();if(!items.some(x=>x.key===selected))selected=items[0]?.key||null;
 worldMenu('鍛冶屋 · ティア強化','<div class="tier-toolbar">'+[['slot','装備中'],['bag','鞄'],['stash','倉庫']].map(([id,label])=>'<button aria-pressed="'+(tierForgeArea===id)+'" onclick="tierForgeArea=\''+id+'\';showTierForge()">'+label+'</button>').join('')+'<button onclick="showForge()">製作に戻る</button></div><div class="tier-layout"><div class="tier-items">'+items.map(({key,item})=>'<button data-tier-item="'+key+'" aria-label="'+gearEscape(item.name)+' ティア '+tierForgeLevel(item)+'" onclick="tierForgeDetail(\''+key+'\');menuFocusElement($(\'tierForgeDetail\').querySelector(\'button:not(:disabled),summary\'))">'+equipmentArt(item)+'<span>'+gearEscape(item.name)+'</span><small>T'+tierForgeLevel(item)+'</small></button>').join('')+(items.length?'':'<p>装備がありません</p>')+'</div><section id="tierForgeDetail" aria-live="polite"></section></div>','tierForge');
 for(const b of $('card').querySelectorAll('[data-tier-item]'))b.addEventListener('focus',()=>tierForgeDetail(b.dataset.tierItem));if(selected)tierForgeDetail(selected);menuFocusElement($('card').querySelector('[data-tier-item="'+selected+'"]')||$('card').querySelector('.tier-toolbar button'));return true;}
const tierForgeMenu=showForge;showForge=(...args)=>{const result=tierForgeMenu(...args);if(menuSurface==='forgeRecipes'){const b=document.createElement('button');b.textContent='ティア強化';b.onclick=()=>showTierForge();$('card').querySelector('.recipe-toolbar')?.append(b);}return result;};
const tierPadBase=padMenu;padMenu=(g,l,r,dt)=>{if(menuSurface==='tierForge'&&padEdge(g,'back')){if(document.activeElement?.closest?.('#tierForgeDetail'))menuFocusElement($('card').querySelector('[data-tier-item="'+tierForgeSelected+'"]'));else showForge();return;}return tierPadBase(g,l,r,dt);};
const tierRevealBase=menuReveal;menuReveal=el=>{const pane=el?.closest?.('.tier-items,#tierForgeDetail');if(pane){menuRevealWithin(pane,el);return tierRevealBase(pane);}return tierRevealBase(el);};
const tierScrollBase=menuScroll;menuScroll=(stick,dt)=>{if(menuSurface==='tierForge'){const pane=document.activeElement?.closest?.('.tier-items,#tierForgeDetail');if(pane){pane.scrollTop+=stick.y*500*dt;return;}}return tierScrollBase(stick,dt);};
